insert into chart_templates
  (country, code, name, name_i18n, is_default, audience, statements,
   certification_status, legal_reference, source_key)
values
  ('TZ', 'default', 'Tanzania reference chart of accounts', '{}'::jsonb, true, 'companies', array['TZ-NBAA-IS', 'TZ-NBAA-SFP']::text[], null, 'There is no legal chart of accounts in Tanzania. Companies Act, 2002 (Cap. 212), s. 151(1) requires every company to keep proper books of account sufficient to disclose the company''s financial position and to enable the directors to ensure that a balance sheet, profit and loss account and cash flow statement comply with the requirements of the Act; s. 153 requires the directors to prepare, for each accounting period, a profit and loss account, a balance sheet and a cash flow statement; s. 154(1) requires each of them to give a true and fair view; s. 154(2) requires them to comply with the requirements prescribed by the Minister or the National Board of Accountants and Auditors, having regard to generally accepted principles of accounting. NBAA, the standard-setting body the Auditors and Accountants (Registration) Act (Cap. 286) recognises, adopted the IFRS Accounting Standards and, for a commercial entity that is not a public-interest entity, the IFRS for SMEs Accounting Standard. This chart is original: four digits, blocked so that each range reaches one line of the IFRS for SMEs statements below, with the accounts a Tanzanian company actually keeps — VAT input and output tax, import VAT owed to TRA at the border, NSSF, Workers Compensation Fund and Skills Development Levy contributions, withholding tax, amounts due to directors.', 'companies-act-2002')
on conflict (country, code) do update set
  name                 = excluded.name,
  name_i18n            = excluded.name_i18n,
  is_default           = excluded.is_default,
  audience             = excluded.audience,
  statements           = excluded.statements,
  certification_status = excluded.certification_status,
  legal_reference      = excluded.legal_reference,
  source_key           = excluded.source_key;

