values
  ('TZ', 'TZ-P-18', 'Purchase, standard rate 18 %, deductible', '{}'::jsonb, 'A local purchase at the general rate, acquired for the purpose of making taxable supplies', 'percent', 18, 'purchase', 'domestic', date '2015-07-01', null, 'Value Added Tax Act, s. 68(1) — a taxable person is allowed a credit for input tax incurred if the goods, services or immovable property were acquired in Mainland Tanzania by the person in the course of the person''s economic activity and for the purpose of making taxable supplies, and the person paid, or is liable to pay, the consideration for the supply.', null, null, 110, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-act', null, null, null, null),
  ('TZ', 'TZ-P-18-BL', 'Purchase, standard rate 18 %, input tax disallowed', '{}'::jsonb, 'Entertainment, a club or association membership, or a passenger vehicle and its running costs, bought other than in the ordinary course of a business that deals in, hires out or provides transport services in them', 'percent', 18, 'purchase', 'domestic', date '2015-07-01', null, 'Value Added Tax Act, s. 68(3) — a taxable person is not allowed an input tax credit for an acquisition, to the extent it is used to provide entertainment (unless the person''s economic activity involves providing entertainment in the ordinary course of that activity); for a membership or right of entry to a club, association or society of a sporting, social or recreational nature; or for the acquisition or import of a passenger vehicle, or of spare parts or repair and maintenance services for one, unless the person''s economic activity involves dealing in, hiring out, or providing transport services in passenger vehicles and the vehicle was acquired for that purpose. The disallowed tax is not a claim on the return, so it lands on the account of the line it taxes and reaches no box.', null, null, 120, 'vat', false, '{}'::tax_condition[], null, false, false, null, 'vat-act', null, null, null, null),
  ('TZ', 'TZ-P-EX', 'Purchase, exempt', '{}'::jsonb, 'An insurance premium, or another exempt supply bought for the business', 'percent', 0, 'purchase', 'exempt', date '2015-07-01', null, 'Value Added Tax Act, s. 6(1); First Schedule, Part I, item 13 — life insurance or health insurance, and insurance for workers compensation, are exempt intermediary services, so there is no value added tax to deduct on the premium.', null, null, 130, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-act', null, null, null, null),
  ('TZ', 'TZ-P-IMP', 'Import of goods, VAT paid at the border', '{}'::jsonb, 'Value added tax collected by the Commissioner General on importation and claimed as input tax once paid', 'percent', 18, 'purchase', 'import', date '2015-07-01', null, 'Value Added Tax Act, s. 8(1) and (3) — the value added tax payable on a taxable import is paid where goods are entered for home consumption, in accordance with the East African Customs Management Act, and the Commissioner General collects it at the time of import; s. 9 — the value of an import; s. 68(1)(c) — input tax includes value added tax paid under this Act on a taxable import. The tax is owed to the Tanzania Revenue Authority at the border and not to the supplier, so it waits on 2125 until the import declaration is settled.', null, null, 140, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-act', null, null, null, null),
  ('TZ', 'TZ-P-RC-IMPSVC', 'Imported service, self-charged and claimed', '{}'::jsonb, 'A service supplied by a person with no place of business in Mainland Tanzania, acquired for a taxable economic activity', 'percent', 18, 'purchase', 'foreign_services_received', date '2015-07-01', null, 'Value Added Tax Act, s. 2(1), definition of "taxable supply", paragraph (b) — a supply of imported services to a taxable person who acquires them in the course of an economic activity is itself a taxable supply where, had the supply been made in Mainland Tanzania, it would have been taxed at a rate other than zero and the purchaser would not have been entitled to a credit for ninety per cent or more of the tax; s. 4(c) — the purchaser of a taxable supply of imported services is the person liable to pay the tax; s. 68(1)(a) and s. 68(2) — input tax includes value added tax payable by the person on a taxable supply of imported services, and the purchaser is not allowed the input tax credit unless the output tax has been accounted for in the same return. Unlike a jurisdiction where a reverse charge reaches only an input-side box, the Tanzanian Act makes the same amount both the purchaser''s output tax and input tax in one return, so this code posts the deemed output liability to box 5 and the matching claim to box 10.', null, null, 150, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-act', null, null, null, null),
  ('TZ', 'TZ-S-18', 'Sale, standard rate 18 %', '{}'::jsonb, 'A taxable supply made in Mainland Tanzania that is neither zero-rated nor exempt', 'percent', 18, 'sale', 'domestic', date '2015-07-01', null, 'Value Added Tax Act (Cap. 148), s. 3 — value added tax is imposed and payable on taxable supplies and taxable imports; s. 5(1) — the amount of value added tax payable is calculated by multiplying the value of the supply by the value added tax rate, which is eighteen per cent. `vat_category` and `exemption_code` are left null: this pack declares no `einvoicing.profile`, so BT-118/BT-151/BT-121 are not terms of any invoice a Mainland Tanzanian company issues.', null, null, 10, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-act', null, null, null, null),
  ('TZ', 'TZ-S-EX-HEALTH', 'Sale, exempt (health care services)', '{}'::jsonb, 'Medical, dental, nursing, rehabilitation or similar services provided by or in an institution approved by the Government and by or under the supervision of a person registered to perform the service', 'percent', 0, 'sale', 'exempt', date '2015-07-01', null, 'Value Added Tax Act, s. 6(1) — except as otherwise provided in this Act or the Schedule, a supply not listed there is not exempt; First Schedule, Part I, item 10(1) — a supply of medical, dental, nursing, convalescent, rehabilitation, midwifery, paramedical, optical or other similar services is exempt where the services are provided by or in an institution approved for their provision by the Government, and by or under the supervision and control of a person registered as qualified to perform that service under Tanzanian law.', null, null, 50, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-act', null, null, null, null),
  ('TZ', 'TZ-S-ZR-EXP', 'Sale, zero-rated (export of goods)', '{}'::jsonb, 'Goods exported from Mainland Tanzania within the meaning the Act gives to "export"', 'percent', 0, 'sale', 'export', date '2015-07-01', null, 'Value Added Tax Act, s. 5(2) — where the supply is zero-rated, the value added tax rate is zero per cent; s. 55(1) — a supply of goods is zero-rated if the goods are exported within the meaning of "export" under s. 2, that is, the removal of goods from a place in Mainland Tanzania to a place outside the United Republic.', null, null, 20, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-act', null, null, null, null),
  ('TZ', 'TZ-S-ZR-SVC', 'Sale, zero-rated (export of services)', '{}'::jsonb, 'A service whose customer is outside the United Republic at the time of supply and who effectively uses or enjoys it there', 'percent', 0, 'sale', 'export', date '2016-07-01', null, 'Value Added Tax Act, s. 61A(1), inserted by the Finance Act, 2016 (Act No. 2 of 2016, s. 96) — a supply of services is zero-rated if the customer is outside the United Republic at the time of supply and effectively uses or enjoys the services outside the United Republic, and the services are neither directly related to land situated in the United Republic nor physically performed on goods situated in the United Republic at the time of supply; s. 61A(2) — not zero-rated where the supply is of a right or option to receive a subsequent supply of something else in the United Republic, or is rendered under an agreement with a non-resident to a person in the United Republic who is not a registered person.', null, null, 30, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-act', null, null, null, null),
  ('TZ', 'TZ-S-ZR-ZNZ', 'Sale, zero-rated (locally manufactured goods supplied to Tanzania Zanzibar)', '{}'::jsonb, 'Locally manufactured goods supplied by a local manufacturer to a taxable person registered under the value added tax law of Tanzania Zanzibar', 'percent', 0, 'sale', 'export', date '2016-07-01', null, 'Value Added Tax Act, s. 55A, inserted by the Finance Act, 2016 (Act No. 2 of 2016, s. 94) — a supply of locally manufactured goods by a local manufacturer is zero-rated if the goods are supplied to a taxable person registered under the value added tax law administered in Tanzania Zanzibar and are removed from Mainland Tanzania without being effectively used or enjoyed in Mainland Tanzania. Zanzibar administers its own value added tax under a separate law, so this movement is zero-rated the way an export to a country outside the United Republic is, and not treated as a domestic supply; `treatment` is declared `export` for that reason, and the gap between this and a true cross-border export is recorded in docs/international.md.', null, null, 40, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-act', null, null, null, null)
on conflict (country, code) do update set
  name            = excluded.name,
  name_i18n       = excluded.name_i18n,
  description     = excluded.description,
  amount_type     = excluded.amount_type,
  amount          = excluded.amount,
  applies_to      = excluded.applies_to,
  treatment       = excluded.treatment,
  valid_from      = excluded.valid_from,
  valid_to        = excluded.valid_to,
  legal_reference = excluded.legal_reference,
  vat_category    = excluded.vat_category,
  exemption_code  = excluded.exemption_code,
  sequence        = excluded.sequence,
  tax_kind        = excluded.tax_kind,
  recoverable     = excluded.recoverable,
  conditions      = excluded.conditions,
  jurisdiction    = excluded.jurisdiction,
  price_include   = excluded.price_include,
  cash_basis      = excluded.cash_basis,
  cash_basis_transition_account_code = excluded.cash_basis_transition_account_code,
  source_key      = excluded.source_key,
  applies_seller_territory = excluded.applies_seller_territory,
  applies_buyer_territory  = excluded.applies_buyer_territory,
  applies_supply_territory = excluded.applies_supply_territory,
  applies_supply_vs_seller = excluded.applies_supply_vs_seller;

