insert into tax_report_templates
  (country, code, name, periods, period_default, valid_from, valid_to, legal_reference,
   is_periodic_return, deadline_rule, deadline_day, deadline_plus_days,
   deadline_reference, deadline_source_key, file_format)
values
  ('TZ', 'TZ-VAT-RETURN', 'VAT return', array['month']::declaration_period[], 'month'::declaration_period, date '2015-07-01', null, 'Value Added Tax Act (Cap. 148), s. 2(1) — a "tax period" means a calendar month; s. 66(1) — a taxable person lodges a value added tax return in the form and manner prescribed by the Minister, on the twentieth day of the month after the tax period, whether or not a net amount is payable for that period; s. 67(1) — the net amount payable is calculated by adding all output tax that becomes payable in the tax period, subtracting all input tax credits allowed in that period, and adjusting the result by any increasing or decreasing adjustments. No box-by-box specification of the on-screen field layout of the Tanzania Revenue Authority''s electronic return (filed through the IDRAS portal, which superseded the paper form ITX 240.02.B) could be independently verified from an official source at the time this pack was written — the archived paper form no longer resolves on tra.go.tz. The boxes below are this pack''s own numbering of the return the Act itself describes in ss. 66 to 68, not a transcription of TRA''s field numbers; a reviewer who can check the current IDRAS screen against them is asked to in packs/tz/README.md.', true,'day_of_month_after_period'::filing_deadline_rule, 20, null, 'Value Added Tax Act, s. 66(1) — the return is lodged, and s. 67(3)(a) — the net amount is paid, on the twentieth day of the month after the tax period; s. 66(7) — where the twentieth day falls on a Saturday, Sunday or public holiday, the return is lodged on the first working day following it.', 'vat-act', null)
on conflict (country, code) do update set
  name                = excluded.name,
  periods             = excluded.periods,
  period_default      = excluded.period_default,
  valid_from          = excluded.valid_from,
  valid_to            = excluded.valid_to,
  legal_reference     = excluded.legal_reference,
  is_periodic_return  = excluded.is_periodic_return,
  deadline_rule       = excluded.deadline_rule,
  deadline_day        = excluded.deadline_day,
  deadline_plus_days  = excluded.deadline_plus_days,
  deadline_reference  = excluded.deadline_reference,
  deadline_source_key = excluded.deadline_source_key,
  file_format         = excluded.file_format;

insert into tax_report_box_templates
  (country, report_code, box, kind, name, name_i18n, sequence, print_sequence,
   plus_boxes, minus_boxes, rate, rate_of_box, floor_zero, hidden, xml_element,
   legal_reference, source_key)
values
  ('TZ', 'TZ-VAT-RETURN', '1', 'base', 'Standard-rated sales — value', '{}'::jsonb, 10, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Value Added Tax Act, s. 5(1) — the value of a taxable supply taxed at the general rate.', 'vat-act'),
  ('TZ', 'TZ-VAT-RETURN', '1', 'tax', 'Standard-rated sales — output VAT', '{}'::jsonb, 15, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Value Added Tax Act, s. 5(1) — the value added tax charged on the supply at eighteen per cent.', 'vat-act'),
  ('TZ', 'TZ-VAT-RETURN', '2', 'base', 'Zero-rated sales', '{}'::jsonb, 20, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Value Added Tax Act, ss. 55, 55A and 61A — exports of goods, locally manufactured goods supplied to Tanzania Zanzibar, and exports of services, all zero-rated under Part IV(b) of the Act.', 'vat-act'),
  ('TZ', 'TZ-VAT-RETURN', '3', 'base', 'Exempt sales', '{}'::jsonb, 30, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Value Added Tax Act, s. 6(1) and the First Schedule — a supply exempted by the Schedule.', 'vat-act'),
  ('TZ', 'TZ-VAT-RETURN', '4', 'total', 'Total sales', '{}'::jsonb, 40, null, array['1:base', '2', '3']::text[], '{}'::text[], null, null, false, false, null, 'The sum of standard-rated, zero-rated and exempt sales for the tax period.', 'vat-act'),
  ('TZ', 'TZ-VAT-RETURN', '5', 'base', 'Imported services — deemed value', '{}'::jsonb, 50, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Value Added Tax Act, s. 2(1), definition of "taxable supply", paragraph (b) — the value of a taxable supply of imported services the purchaser is deemed to have made to itself.', 'vat-act'),
  ('TZ', 'TZ-VAT-RETURN', '5', 'tax', 'Imported services — output VAT self-charged', '{}'::jsonb, 55, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Value Added Tax Act, s. 4(c) and s. 2(1) definition of "output tax", paragraph (b) — value added tax payable by the purchaser on a taxable supply of imported services acquired.', 'vat-act'),
  ('TZ', 'TZ-VAT-RETURN', '6', 'total', 'Total output tax', '{}'::jsonb, 60, null, array['1:tax', '5:tax']::text[], '{}'::text[], null, null, false, false, null, 'Value Added Tax Act, s. 67(1)(a) — all output tax that becomes payable by the taxable person in the tax period.', 'vat-act'),
  ('TZ', 'TZ-VAT-RETURN', '7', 'base', 'Standard-rated purchases — value', '{}'::jsonb, 70, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Value Added Tax Act, s. 68(1) — the value of a local purchase whose input tax is claimable.', 'vat-act'),
  ('TZ', 'TZ-VAT-RETURN', '7', 'tax', 'Standard-rated purchases — input VAT', '{}'::jsonb, 75, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Value Added Tax Act, s. 68(1) — the input tax credit allowed on the purchase.', 'vat-act'),
  ('TZ', 'TZ-VAT-RETURN', '8', 'base', 'Exempt purchases', '{}'::jsonb, 80, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Value Added Tax Act, s. 6(1) and the First Schedule — a purchase exempted by the Schedule, carrying no value added tax to deduct.', 'vat-act'),
  ('TZ', 'TZ-VAT-RETURN', '9', 'base', 'Import of goods — value', '{}'::jsonb, 90, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Value Added Tax Act, s. 9 — the value of an import of goods.', 'vat-act'),
  ('TZ', 'TZ-VAT-RETURN', '9', 'tax', 'Import of goods — input VAT', '{}'::jsonb, 95, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Value Added Tax Act, s. 8 and s. 68(1)(c) — value added tax paid to the Commissioner General on a taxable import, claimed as input tax.', 'vat-act'),
  ('TZ', 'TZ-VAT-RETURN', '10', 'tax', 'Imported services — input VAT claimed', '{}'::jsonb, 100, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Value Added Tax Act, s. 68(1)(a) and s. 68(2) — value added tax payable on a taxable supply of imported services is also input tax of the purchaser, claimable once the matching output tax is accounted for in the same return.', 'vat-act'),
  ('TZ', 'TZ-VAT-RETURN', '11', 'total', 'Total purchases', '{}'::jsonb, 110, null, array['7:base', '8', '9:base']::text[], '{}'::text[], null, null, false, false, null, 'The sum of standard-rated, exempt and imported purchases for the tax period.', 'vat-act'),
  ('TZ', 'TZ-VAT-RETURN', '12', 'total', 'Total input tax credit', '{}'::jsonb, 120, null, array['7:tax', '9:tax', '10']::text[], '{}'::text[], null, null, false, false, null, 'Value Added Tax Act, s. 67(1)(b) — all input tax credits allowed in the tax period.', 'vat-act'),
  ('TZ', 'TZ-VAT-RETURN', '13', 'total', 'Net VAT payable / (credit)', '{}'::jsonb, 130, null, array['6']::text[], array['12']::text[], null, null, false, false, null, 'Value Added Tax Act, s. 67(1) and (3) — the net amount payable for the tax period is output tax less input tax credits, adjusted for any increasing or decreasing adjustment; a positive amount is accounted for and paid by the day the return is due, s. 67(3)(a); a negative amount is a negative net amount, carried forward under s. 81 or refunded within the conditions s. 82 sets, neither of which this pack carries — see packs/tz/README.md.', 'vat-act')
on conflict (country, report_code, box, kind) do update set
  name            = excluded.name,
  name_i18n       = excluded.name_i18n,
  sequence        = excluded.sequence,
  print_sequence  = excluded.print_sequence,
  plus_boxes      = excluded.plus_boxes,
  minus_boxes     = excluded.minus_boxes,
  rate            = excluded.rate,
  rate_of_box     = excluded.rate_of_box,
  floor_zero      = excluded.floor_zero,
  hidden          = excluded.hidden,
  xml_element     = excluded.xml_element,
  legal_reference = excluded.legal_reference,
  source_key      = excluded.source_key;

insert into statement_templates
  (code, country, chart_code, name, kind, framework, valid_from, valid_to, legal_reference,
   source_key)
values
  ('TZ-NBAA-IS', 'TZ', 'default', 'Profit and loss account', 'income_statement', 'IFRS-SME', date '2018-01-01', null, 'Companies Act, 2002 (Cap. 212), s. 153(a) — the directors prepare a profit and loss account for each accounting period; s. 154(1) — it gives a true and fair view of the profit or loss of the company for the accounting period. The IFRS for SMEs Accounting Standard''s illustrative statement of comprehensive income aggregates expenses by nature, which these lines follow.', 'companies-act-2002'),
  ('TZ-NBAA-SFP', 'TZ', 'default', 'Statement of financial position', 'balance_sheet', 'IFRS-SME', date '2018-01-01', null, 'Companies Act, 2002 (Cap. 212), s. 153 — the directors of every company prepare individual accounts for each accounting period indicating a profit and loss account, a balance sheet as at the last day of the accounting period, and a cash flow statement; s. 154(1) — the balance sheet gives a true and fair view of the state of affairs of the company as at the end of its accounting period; s. 154(2) — a company''s balance sheet, profit and loss account and cash flow statement comply with the requirements specified in regulations prescribed by the Minister, or the National Board of Accountants and Auditors, having regard to generally accepted principles of accounting. The National Board of Accountants and Auditors, the standard-setting body the Auditors and Accountants (Registration) Act (Cap. 286) entrusts, adopted the IFRS for SMEs Accounting Standard with effect from 2010 and, by its 2018 technical pronouncement, requires a commercial enterprise that is not a public-interest entity with an annual turnover of TZS 800,000,000 or more and total assets of TZS 400,000,000 or more to report under it; the lines below follow the statement of financial position that Standard sets out at section 4. This pack does not carry a cash flow statement or a statement of changes in equity: `statements.json` knows a `balance_sheet` and an `income_statement`, and no third kind of statement.', 'companies-act-2002')
on conflict (code) do update set
  country         = excluded.country,
  chart_code      = excluded.chart_code,
