update country_defaults set
  numbering_gapless             = false,
  number_format                 = '{CODE}-{YYYY}-{NNNN}',
  legal_payment_days            = null,
  late_payment_reference        = null,
  numbering_legal_reference     = 'Value Added Tax Act, s. 86(1) — a registered person making a taxable supply issues, no later than the day value added tax becomes payable on it, a serially numbered true and correct tax invoice generated by an electronic fiscal device; the section asks that each invoice be identified in sequence by the device, and not that a company''s own document series carry no gap, which is why the style is `sequential`.',
  numbering_source_key          = 'vat-act',
  payment_terms_legal_reference = null,
  payment_terms_source_key      = null,
  tax_point_rule                = 'earliest_of_delivery_or_payment',
  tax_point_legal_reference     = 'Value Added Tax Act, s. 15 — value added tax imposed on a taxable supply becomes payable at the EARLIEST of: (a) the time the invoice for the supply is issued by the supplier; (b) the time the consideration is received, in whole or in part; or (c) the time of supply. This is a three-way earliest-of test, and Ekwo''s closed vocabulary expresses only a two-way one; `earliest_of_delivery_or_payment` is the nearer of the two derogation values, matching branches (b) and (c) of section 15. The gap — an invoice issued ahead of both delivery and payment, which fixes the tax point in Tanzania under branch (a) but which this value does not itself read — is recorded in docs/international.md, the same reading Bosnia and Herzegovina''s three-way test under article 17(1) was given.',
  tax_point_source_key          = 'vat-act',
  posted_edit_policy            = null,
  posted_edit_policy_legal_reference = null,
  posted_edit_policy_source_key = null,
  einvoice_profile              = null,
  einvoice_mandatory_from       = null,
  einvoice_obligation           = 'none',
  einvoice_legal_reference      = 'No Tanzanian statute obliges a business to exchange a structured electronic invoice with another business, or to accept one, in the sense Ekwo''s vocabulary gives the word — there is no Tanzanian Peppol authority, no published profile and no ISO 6523 scheme a party is addressed by, so `profile`, `party_scheme` and `vat_scheme` are all null and `obligation` is `none`. What Tanzania has instead is a clearance system built into the tax invoice itself: Value Added Tax Act, s. 86(1) requires a registered person to issue, no later than the day the tax becomes payable, a serially numbered true and correct tax invoice generated by an electronic fiscal device (EFD) or, since 2020, its software equivalent, a virtual fiscal device (VFD); the device or the VFD channel reports the transaction to the Tanzania Revenue Authority''s Electronic Fiscal Device Management System in real time. This validates an invoice already addressed to a Tanzanian buyer through the seller''s own device, and is not a peer-to-peer exchange of a structured document between two businesses in the sense `einvoicing.profile` describes; the gap is recorded in docs/international.md and in this pack''s README, and the socle is not patched to fit it.',
  einvoice_source_key           = 'vat-act',
  party_scheme                  = null,
  vat_scheme                    = null,
  bank_statement_formats        = null,
  payment_formats               = null,
  fiscal_year_default           = 'calendar'
 where country = 'TZ';
